    const referrerHost = luxTargetHost(req.referrer);
    const compatibilityContext = [targetHost, referrerHost].some(h => h === "twitch.tv" || h.endsWith(".twitch.tv") || h === "roblox.com" || h.endsWith(".roblox.com"));
